CREATE TABLE IF NOT EXISTS clients ( id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC', logo_url TEXT, website TEXT, badge_qr_url TEXT, join_code TEXT, join_code_created_at INTEGER, created_at INTEGER NOT NULL ); CREATE UNIQUE INDEX IF NOT EXISTS clients_join_code ON clients(join_code); CREATE TABLE IF NOT EXISTS teams ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, created_at INTEGER NOT NULL ); CREATE UNIQUE INDEX IF NOT EXISTS teams_client_name ON teams(client_id, lower(name)); CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('super_admin','client_admin','manager','field_rep')), phone TEXT, password_hash TEXT, password_salt TEXT, active INTEGER NOT NULL DEFAULT 1, avatar_url TEXT, first_name TEXT, last_name TEXT, job_title TEXT, team_id TEXT REFERENCES teams(id) ON DELETE SET NULL, onboarding_step TEXT, onboarding_version INTEGER NOT NULL DEFAULT 0, onboarding_completed_at INTEGER, walkthrough_completed_at INTEGER, setup_completed_at INTEGER, location_status TEXT, notification_status TEXT, badge_id TEXT, badge_issued_at INTEGER, badge_expires_at INTEGER, badge_confirmed_at INTEGER, last_seen_at INTEGER, created_at INTEGER NOT NULL ); CREATE UNIQUE INDEX IF NOT EXISTS users_badge_id ON users(badge_id); CREATE UNIQUE INDEX IF NOT EXISTS users_client_email ON users(client_id, lower(email)); CREATE INDEX IF NOT EXISTS users_by_client ON users(client_id); CREATE TABLE IF NOT EXISTS territories ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, rep_id TEXT REFERENCES users(id) ON DELETE SET NULL, boundary TEXT ); CREATE TABLE IF NOT EXISTS territory_reps ( territory_id TEXT NOT NULL REFERENCES territories(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, assigned_at INTEGER NOT NULL, assigned_by TEXT REFERENCES users(id) ON DELETE SET NULL, PRIMARY KEY (territory_id, user_id) ); CREATE INDEX IF NOT EXISTS territory_reps_by_user ON territory_reps(user_id); CREATE TABLE IF NOT EXISTS properties ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, address1 TEXT NOT NULL, city TEXT, state TEXT, zip TEXT, lat REAL NOT NULL, lng REAL NOT NULL, status TEXT NOT NULL DEFAULT 'new', score INTEGER NOT NULL DEFAULT 50, opportunity_value INTEGER, owner_occupied INTEGER, roof_age_years INTEGER, square_feet INTEGER, last_outcome TEXT, last_visit_at INTEGER, next_action_at INTEGER, next_action_label TEXT, territory_id TEXT REFERENCES territories(id) ON DELETE SET NULL, assigned_rep_id TEXT REFERENCES users(id) ON DELETE SET NULL, tags TEXT, geo_precision TEXT, geo_provider TEXT, address_confidence TEXT, address_source TEXT, residential_status TEXT, plan_id TEXT REFERENCES plans(id) ON DELETE SET NULL, updated_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS properties_by_rep ON properties(client_id, assigned_rep_id); CREATE INDEX IF NOT EXISTS properties_by_territory ON properties(territory_id); CREATE TABLE IF NOT EXISTS contacts ( id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, name TEXT NOT NULL, phone TEXT, email TEXT, relationship TEXT, is_primary INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS contacts_by_property ON contacts(property_id); CREATE TABLE IF NOT EXISTS routes ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, name TEXT NOT NULL, started_at INTEGER ); CREATE INDEX IF NOT EXISTS routes_by_rep_date ON routes(rep_id, date); CREATE TABLE IF NOT EXISTS route_stops ( route_id TEXT NOT NULL REFERENCES routes(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, ord INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', completed_at INTEGER, PRIMARY KEY (route_id, property_id) ); CREATE TABLE IF NOT EXISTS visits ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, started_at INTEGER NOT NULL, ended_at INTEGER, outcome TEXT, duration_ms INTEGER, start_lat REAL, start_lng REAL, start_accuracy REAL, next_action_at INTEGER, next_action_type TEXT ); CREATE INDEX IF NOT EXISTS visits_by_property ON visits(property_id); CREATE INDEX IF NOT EXISTS visits_by_rep_time ON visits(rep_id, started_at); CREATE TABLE IF NOT EXISTS notes ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, visit_id TEXT REFERENCES visits(id) ON DELETE SET NULL, body TEXT NOT NULL DEFAULT '', tags TEXT, author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS notes_by_property ON notes(property_id); CREATE TABLE IF NOT EXISTS photos ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, visit_id TEXT REFERENCES visits(id) ON DELETE SET NULL, category TEXT NOT NULL, type TEXT, r2_key TEXT NOT NULL, width INTEGER, height INTEGER, bytes INTEGER, captured_lat REAL, captured_lng REAL, created_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS photos_by_property ON photos(property_id); CREATE TABLE IF NOT EXISTS appointments ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, starts_at INTEGER NOT NULL, duration_min INTEGER NOT NULL DEFAULT 45, title TEXT NOT NULL, contact_id TEXT, notes TEXT ); CREATE INDEX IF NOT EXISTS appointments_by_rep ON appointments(rep_id, starts_at); CREATE TABLE IF NOT EXISTS tasks ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, property_id TEXT REFERENCES properties(id) ON DELETE CASCADE, title TEXT NOT NULL, due_at INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'follow_up' ); CREATE INDEX IF NOT EXISTS tasks_by_rep_due ON tasks(rep_id, due_at); CREATE TABLE IF NOT EXISTS activity ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, summary TEXT NOT NULL, outcome TEXT, at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS activity_by_client_time ON activity(client_id, at DESC); CREATE TABLE IF NOT EXISTS daily_stats ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day TEXT NOT NULL, knocks INTEGER NOT NULL DEFAULT 0, conversations INTEGER NOT NULL DEFAULT 0, appointments INTEGER NOT NULL DEFAULT 0, quotes INTEGER NOT NULL DEFAULT 0, sold INTEGER NOT NULL DEFAULT 0, pipeline_value INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS daily_stats_by_client_day ON daily_stats(client_id, day); CREATE TABLE IF NOT EXISTS plans ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, value INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS plans_by_client ON plans(client_id, sort); CREATE TABLE IF NOT EXISTS deals ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT REFERENCES users(id) ON DELETE SET NULL, plan_id TEXT REFERENCES plans(id) ON DELETE SET NULL, plan_name TEXT, plan_value INTEGER, value INTEGER NOT NULL DEFAULT 0, value_overridden_by TEXT REFERENCES users(id) ON DELETE SET NULL, override_reason TEXT, status TEXT NOT NULL DEFAULT 'won', won_at INTEGER NOT NULL, visit_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS deals_by_client_won ON deals(client_id, status, won_at); CREATE INDEX IF NOT EXISTS deals_by_rep_won ON deals(rep_id, won_at); CREATE UNIQUE INDEX IF NOT EXISTS deals_by_property ON deals(property_id); CREATE TABLE IF NOT EXISTS applied_mutations ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL, user_id TEXT NOT NULL, kind TEXT NOT NULL, applied_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS applied_mutations_time ON applied_mutations(applied_at); CREATE TABLE IF NOT EXISTS invites ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, accepted_at INTEGER, opened_at INTEGER, revoked_at INTEGER, kind TEXT NOT NULL DEFAULT 'invite' ); CREATE INDEX IF NOT EXISTS invites_by_user ON invites(user_id); CREATE TABLE IF NOT EXISTS client_settings ( client_id TEXT PRIMARY KEY REFERENCES clients(id) ON DELETE CASCADE, settings TEXT NOT NULL, updated_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS audit_log ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, actor_id TEXT REFERENCES users(id) ON DELETE SET NULL, actor_name TEXT NOT NULL, action TEXT NOT NULL, target_type TEXT, target_id TEXT, target_label TEXT, detail TEXT, at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS audit_by_client_time ON audit_log(client_id, at DESC); CREATE TABLE IF NOT EXISTS error_log ( id TEXT PRIMARY KEY, client_id TEXT, user_id TEXT, at INTEGER NOT NULL, method TEXT, route TEXT, status INTEGER NOT NULL, operation TEXT, records INTEGER, message TEXT, ms INTEGER ); CREATE INDEX IF NOT EXISTS error_log_by_client ON error_log(client_id, at DESC); CREATE TABLE IF NOT EXISTS login_attempts ( id TEXT PRIMARY KEY, window_start INTEGER NOT NULL, attempts INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS sessions ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS sessions_by_user ON sessions(user_id); CREATE TABLE IF NOT EXISTS client_integrations ( client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, provider TEXT NOT NULL, auth_type TEXT NOT NULL DEFAULT 'pit', access_token TEXT NOT NULL, refresh_token TEXT, expires_at INTEGER, location_id TEXT, config TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'active', last_ok_at INTEGER, last_error TEXT, last_error_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (client_id, provider) ); CREATE TABLE IF NOT EXISTS client_geocoders ( client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, provider TEXT NOT NULL, api_key TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', last_ok_at INTEGER, last_error TEXT, last_error_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (client_id, provider) ); CREATE UNIQUE INDEX IF NOT EXISTS client_geocoders_active ON client_geocoders(client_id) WHERE active = 1; CREATE TABLE IF NOT EXISTS geocode_usage ( client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, provider TEXT NOT NULL, day TEXT NOT NULL, lookups INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (client_id, provider, day) ); CREATE TABLE IF NOT EXISTS deletions ( client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, entity TEXT NOT NULL, entity_id TEXT NOT NULL, actor_id TEXT, actor_name TEXT, reason TEXT, photos INTEGER NOT NULL DEFAULT 0, at INTEGER NOT NULL, PRIMARY KEY (client_id, entity, entity_id) ); CREATE INDEX IF NOT EXISTS deletions_by_client ON deletions(client_id, at); CREATE TABLE IF NOT EXISTS sync_conflicts ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT REFERENCES users(id) ON DELETE SET NULL, kind TEXT NOT NULL, acted_at INTEGER NOT NULL, arrived_at INTEGER NOT NULL, changed_at INTEGER NOT NULL, detail TEXT, reviewed_at INTEGER ); CREATE INDEX IF NOT EXISTS sync_conflicts_open ON sync_conflicts(client_id, reviewed_at, arrived_at); CREATE TABLE IF NOT EXISTS lead_lists ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, boundary TEXT, archived INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS lead_lists_by_client ON lead_lists(client_id, archived); CREATE TABLE IF NOT EXISTS lead_list_members ( list_id TEXT NOT NULL REFERENCES lead_lists(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, added_at INTEGER NOT NULL, added_by TEXT REFERENCES users(id) ON DELETE SET NULL, PRIMARY KEY (list_id, property_id) ); CREATE INDEX IF NOT EXISTS lead_list_members_by_property ON lead_list_members(property_id); CREATE TABLE IF NOT EXISTS lead_list_reps ( list_id TEXT NOT NULL REFERENCES lead_lists(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, assigned_at INTEGER NOT NULL, assigned_by TEXT REFERENCES users(id) ON DELETE SET NULL, PRIMARY KEY (list_id, user_id) ); CREATE INDEX IF NOT EXISTS lead_list_reps_by_user ON lead_list_reps(user_id); CREATE TABLE IF NOT EXISTS integration_links ( client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, provider TEXT NOT NULL, kind TEXT NOT NULL, local_id TEXT NOT NULL, remote_id TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (client_id, provider, kind, local_id) ); CREATE UNIQUE INDEX IF NOT EXISTS integration_links_remote ON integration_links(client_id, provider, kind, remote_id); CREATE TABLE IF NOT EXISTS integration_outbox ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, provider TEXT NOT NULL, event TEXT NOT NULL, payload TEXT NOT NULL, dedupe_key TEXT, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at INTEGER NOT NULL, last_error TEXT, created_at INTEGER NOT NULL, sent_at INTEGER ); CREATE INDEX IF NOT EXISTS integration_outbox_due ON integration_outbox(status, next_attempt_at); CREATE UNIQUE INDEX IF NOT EXISTS integration_outbox_dedupe ON integration_outbox(client_id, provider, dedupe_key) WHERE dedupe_key IS NOT NULL AND status = 'pending';
